export const RESUME_SHELL = "<meta charset=\"utf-8\">\n<title>Josh Cole — Creative Technologist · AI</title>\n<meta name=\"author\" content=\"Josh Cole\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\n<!--\n  Josh Cole — resume\n  Source of truth. The .docx and .pdf are derivatives; regenerate, never edit.\n\n  EXPORT: Chrome/Brave → Print → Destination \"Save as PDF\"\n          Margins: DEFAULT  — not \"None\". \"None\" forces margins to zero and\n                              overrides the @page rule below, printing the\n                              content edge to edge.\n          \"Background graphics\": ON   (the gradient rule under the name)\n\n  FONTS: loaded from Google Fonts below for portability. To self-host from\n  joshcolecreative.com instead, delete the two <link> tags and point the\n  @font-face at your own /fonts directory. Same families either way.\n-->\n\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Syne:wght@600;700&family=Inter:ital,wght@0,400;0,500;0,600;1,400&family=JetBrains+Mono:wght@400;500&display=swap\" rel=\"stylesheet\">\n\n<style>\n  /* ---------------------------------------------------------------\n     TOKENS — paper variant of the joshcolecreative.com system.\n     Ink is the dark base lifted off pure black; the gradient is the\n     brand gradient, unchanged.\n  --------------------------------------------------------------- */\n  :root {\n    --ink:        #17181d;   /* body text */\n    --ink-strong: #0d0e12;   /* name, role titles */\n    --ink-muted:  #5a5b63;   /* role summaries, earlier-career detail */\n    --ink-label:  #6a6a70;   /* section labels, dates */\n    --rule:       #d8d9de;   /* hairlines */\n    --grad:       linear-gradient(90deg, #26C5FF 0%, #CA43FF 52%, #FF419F 100%);\n\n    --display: \"Syne\", Georgia, serif;\n    --body:    \"Inter\", \"Helvetica Neue\", Arial, sans-serif;\n    --mono:    \"JetBrains Mono\", \"SFMono-Regular\", Consolas, monospace;\n  }\n\n  /* ---------------------------------------------------------------\n     PAGE\n  --------------------------------------------------------------- */\n  /* Vertical margins come from @page; horizontal comes from .sheet padding\n     in print. Splitting them this way means a \"Margins: None\" export still\n     keeps its side margins instead of going fully edge to edge. */\n  @page { size: letter; margin: 0.5in 0; }\n\n  * { box-sizing: border-box; }\n\n  html { background: #e9eaee; }\n\n  body {\n    margin: 0;\n    font-family: var(--body);\n    font-size: 9.1pt;\n    line-height: 1.35;\n    color: var(--ink);\n    -webkit-font-smoothing: antialiased;\n    text-rendering: optimizeLegibility;\n  }\n\n  /* Screen preview only — simulates the sheet. Removed in print. */\n  .sheet {\n    width: 7.4in;               /* 8.5in less the 0.55in page margins */\n    margin: 28px auto;\n    padding: 36px 40px;\n    background: #fff;\n    box-shadow: 0 1px 3px rgba(0,0,0,.14), 0 12px 34px rgba(0,0,0,.10);\n  }\n\n\n  /* ---------------------------------------------------------------\n     TOOLBAR — screen only, never printed.\n  --------------------------------------------------------------- */\n  .toolbar {\n    width: 7.4in;\n    margin: 28px auto -14px;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n  }\n  .toolbar button {\n    font-family: var(--mono);\n    font-size: 8.5pt;\n    letter-spacing: 0.04em;\n    color: var(--ink);\n    background: #fff;\n    border: 1px solid #c9cad0;\n    border-radius: 0;\n    padding: 7px 12px;\n    cursor: pointer;\n    transition: border-color .12s ease, color .12s ease;\n  }\n  .toolbar button:hover { border-color: #8a8b93; }\n  .toolbar button:focus-visible { outline: 2px solid #26C5FF; outline-offset: 2px; }\n  .toolbar .status {\n    font-family: var(--mono);\n    font-size: 8pt;\n    color: var(--ink-muted);\n    opacity: 0;\n    transition: opacity .15s ease;\n  }\n  .toolbar .status.on { opacity: 1; }\n  @media print { .toolbar { display: none !important; } }\n  @media screen and (max-width: 820px) {\n    .toolbar { width: auto; margin: 16px 20px -8px; flex-wrap: wrap; }\n  }\n  @media (prefers-reduced-motion: reduce) {\n    .toolbar button, .toolbar .status { transition: none; }\n  }\n\n  /* ---------------------------------------------------------------\n     MASTHEAD\n     Name is live text, never an image — a resume whose header is an\n     SVG parses as a nameless document.\n  --------------------------------------------------------------- */\n  .name {\n    font-family: var(--display);\n    font-weight: 700;\n    font-size: 25pt;\n    line-height: 1;\n    letter-spacing: -0.005em;\n    color: var(--ink-strong);\n    margin: 0;\n  }\n\n  .discipline {\n    font-family: var(--mono);\n    font-size: 8pt;\n    letter-spacing: 0.1em;\n    text-transform: uppercase;\n    color: var(--ink-label);\n    margin: 7px 0 0;\n  }\n\n  /* The one signature moment. Everything else stays ink and gray. */\n  .grad-rule {\n    height: 2.5px;\n    background: var(--grad);\n    margin: 11px 0 9px;\n    -webkit-print-color-adjust: exact;\n    print-color-adjust: exact;\n  }\n\n  .contact {\n    font-family: var(--mono);\n    font-size: 7.6pt;\n    letter-spacing: 0.01em;\n    color: var(--ink-muted);\n    margin: 0;\n  }\n  .contact a { color: inherit; text-decoration: none; }\n  .contact .sep { color: #b6b7bd; padding: 0 5px; }\n\n  /* ---------------------------------------------------------------\n     SECTIONS\n  --------------------------------------------------------------- */\n  .section { margin-top: 12px; }\n\n  .section > h2 {\n    font-family: var(--mono);\n    font-weight: 500;\n    font-size: 7.4pt;\n    letter-spacing: 0.11em;\n    text-transform: uppercase;\n    color: var(--ink-label);\n    margin: 0 0 8px;\n    padding-bottom: 5px;\n    border-bottom: 1px solid var(--rule);\n  }\n\n  /* ---------------------------------------------------------------\n     SUMMARY\n  --------------------------------------------------------------- */\n  .summary p { margin: 0 0 6px; }\n  .summary p:last-child { margin-bottom: 0; }\n\n  /* ---------------------------------------------------------------\n     SKILLS\n  --------------------------------------------------------------- */\n  .skill { margin: 0 0 5px; }\n  .skill:last-child { margin-bottom: 0; }\n  .skill b {\n    font-weight: 600;\n    color: var(--ink-strong);\n  }\n\n  /* ---------------------------------------------------------------\n     ROLES\n     Single column, no tables, no text boxes. Title and company sit\n     ahead of the date in DOM order so parsers read them in sequence.\n  --------------------------------------------------------------- */\n  /* Roles may break across pages — forcing whole-role atomicity leaves\n     large gaps at page bottoms. What must not split: a title from its\n     summary, and a bullet from itself. */\n  .role { margin-bottom: 9px; }\n  .role:last-child { margin-bottom: 0; }\n\n  .role-head {\n    break-after: avoid;\n    page-break-after: avoid;\n    display: flex;\n    align-items: baseline;\n    justify-content: space-between;\n    gap: 16px;\n  }\n\n  .role-title {\n    font-weight: 600;\n    font-size: 10pt;\n    color: var(--ink-strong);\n    margin: 0;\n    line-height: 1.3;\n  }\n  .role-title .org { font-weight: 400; color: var(--ink); }\n  .role-title .qual { font-weight: 400; color: var(--ink-muted); }\n\n  /* The date column reads as a timeline down the right edge. */\n  .role-date {\n    font-family: var(--mono);\n    font-size: 7.8pt;\n    color: var(--ink-label);\n    white-space: nowrap;\n    flex-shrink: 0;\n  }\n\n  .role-summary {\n    break-after: avoid;\n    page-break-after: avoid;\n    font-style: italic;\n    color: var(--ink-muted);\n    margin: 2px 0 4px;\n  }\n\n  .role ul {\n    list-style: none;\n    margin: 0;\n    padding: 0;\n  }\n  .role li {\n    break-inside: avoid;\n    page-break-inside: avoid;\n    position: relative;\n    padding-left: 12px;\n    margin-bottom: 2.5px;\n  }\n  .role li:last-child { margin-bottom: 0; }\n  .role li::before {\n    content: \"\";\n    position: absolute;\n    left: 0;\n    top: 0.52em;\n    width: 3px;\n    height: 3px;\n    background: #a9aab1;\n    -webkit-print-color-adjust: exact;\n    print-color-adjust: exact;\n  }\n\n  /* ---------------------------------------------------------------\n     EARLIER CAREER — same structure, tightened\n  --------------------------------------------------------------- */\n  .earlier .role { margin-bottom: 5px; break-inside: avoid; page-break-inside: avoid; }\n  .earlier .role-title { font-size: 9.3pt; }\n  .earlier li { color: var(--ink-muted); }\n\n  /* ---------------------------------------------------------------\n     PRINT\n  --------------------------------------------------------------- */\n  @media print {\n    html { background: #fff; }\n    .sheet {\n      width: auto;\n      margin: 0;\n      padding: 0 0.55in;   /* side margins — applies on every page */\n      box-shadow: none;\n    }\n    .section { break-inside: auto; }\n    .section > h2 { break-after: avoid; page-break-after: avoid; }\n    a { color: inherit; text-decoration: none; }\n  }\n\n  /* ---------------------------------------------------------------\n     SMALL SCREENS — preview only\n  --------------------------------------------------------------- */\n  @media screen and (max-width: 820px) {\n    .sheet { width: auto; margin: 0; padding: 24px 20px; }\n    .role-head { flex-direction: column; gap: 1px; }\n  }\n</style>\n\n<script type=\"text/plain\" id=\"plaintext\">%%PLAINTEXT%%</script>\n\n<div class=\"toolbar\" role=\"group\" aria-label=\"Resume download options\">\n  <button type=\"button\" id=\"btn-copy\">Copy plain text</button>\n  <button type=\"button\" id=\"btn-pdf\">Save as PDF</button>\n  <button type=\"button\" id=\"btn-txt\">Download .txt</button>\n  <span class=\"status\" id=\"status\" role=\"status\" aria-live=\"polite\"></span>\n</div>\n\n<div class=\"sheet\">%%BODY%%\n</div>\n\n<script>\n(function () {\n  var src    = document.getElementById('plaintext');\n  var status = document.getElementById('status');\n  var text   = src ? src.textContent.replace(/^\\n/, '') : '';\n\n  function flash(msg) {\n    status.textContent = msg;\n    status.classList.add('on');\n    clearTimeout(flash._t);\n    flash._t = setTimeout(function () { status.classList.remove('on'); }, 2200);\n  }\n\n  document.getElementById('btn-copy').addEventListener('click', function () {\n    function fallback() {\n      var ta = document.createElement('textarea');\n      ta.value = text;\n      ta.setAttribute('readonly', '');\n      ta.style.cssText = 'position:absolute;left:-9999px;top:0';\n      document.body.appendChild(ta);\n      ta.select();\n      var ok = false;\n      try { ok = document.execCommand('copy'); } catch (e) {}\n      document.body.removeChild(ta);\n      flash(ok ? 'Copied' : 'Copy failed — use Download .txt');\n    }\n    // clipboard API needs a secure context; file:// is not one, so fall back\n    if (navigator.clipboard && window.isSecureContext) {\n      navigator.clipboard.writeText(text).then(function () { flash('Copied'); }, fallback);\n    } else {\n      fallback();\n    }\n  });\n\n  document.getElementById('btn-txt').addEventListener('click', function () {\n    var url = URL.createObjectURL(new Blob([text], { type: 'text/plain;charset=utf-8' }));\n    var a = document.createElement('a');\n    a.href = url;\n    a.download = 'josh-cole-resume.txt';\n    document.body.appendChild(a);\n    a.click();\n    document.body.removeChild(a);\n    setTimeout(function () { URL.revokeObjectURL(url); }, 1000);\n    flash('Downloaded');\n  });\n\n  // Opens the print dialog so the PDF comes from the browser's own renderer —\n  // full type quality, real text layer. Client-side PDF libraries rasterize\n  // the page and produce a file no applicant tracking system can read.\n  // ON THE LIVE SITE: replace this with a link to a PDF built at deploy time.\n  document.getElementById('btn-pdf').addEventListener('click', function () {\n    window.print();\n  });\n})();\n</script>\n";
